MAP
    NAME "SS_MAP_GRAL_EFICIENCIA_FISICA"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE 'includes/temp_directory.map'
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END  #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_delimitacion_patron.log"
    DEBUG 0
    LAYER
        PROJECTION
            'init=epsg:32614'
        END #PROJECTION
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_GRAL_EFICIENCIA_FISICA"
        METADATA
            'ows_title' 'Delimitacion_Patron'
            'ows_include_items' 'all'
            'gml_include_items' 'all'
            'wfs_request_method' 'GET'
        END #METADATA
        INCLUDE 'includes/conexion.map' 
 	    DATA "gm_zona_influencia from mv_cuenta_giro_eficiencia_fisica using unique id_elemento_geografico using srid=32614"
	    LABELITEM "nb_zona_influencia"
        STATUS DEFAULT
        TYPE POLYGON
        CLASS
            NAME "Nombre área Delimitación Control E.F."
            STYLE
                COLOR 249 136 180
                OUTLINECOLOR 5 5 255
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT 'ARIAL'
                SIZE 19
                PARTIALS FALSE
                COLOR 5 5 255
                OUTLINECOLOR 254 254 254
            END #LABEL

        END #CLASS
    END #LAYER
END #MAP
